from pathlib import Path

# One-shot verified integration for the final v21 hardening domain layer.
def replace(path, old, new, count=1):
    p=Path(path); text=p.read_text()
    found=text.count(old)
    if found < count: raise SystemExit(f'Missing anchor in {path}: {old[:120]!r} (found {found})')
    p.write_text(text.replace(old,new,count))

def insert_after(path, anchor, addition):
    replace(path,anchor,anchor+addition,1)

